#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.scratch/v1-substituir-mobills/35-resultado.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: roteiro do ticket 35 (teste manual nos dois celulares).
# Os resultados ficam em 35-resultado.env (chave R_<n>) e vão para "## Answer".
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=15
RESULTADOS=()

# registrar CHAVE "descrição": pergunta ok/falhou e uma nota; guarda no .env.
registrar() {
  local chave="$1" desc="$2" r="" n=""
  printf '\n'
  read -e -r -p "  Resultado de \"$desc\" [ok/falhou/pulei]: " r || true
  read -e -r -p "  Nota (medidas, erro, decisão; Enter p/ nenhuma): " n || true
  write_env "$chave" "${r:-pulei} | ${n}"
  RESULTADOS+=("- $desc: ${r:-pulei}${n:+ ($n)}")
}

mkdir -p "$(dirname "$ENV_FILE")"
banner "Ticket 35: teste manual nos dois celulares"

stage "Preparação"
say "Você precisa: iPhone, Android, o endereço do app (dev ou prod) e acesso ao DSQL e à AWS."
note "Resultados vão para $ENV_FILE; reexecutar mantém o que já foi respondido."
ask URL_APP "Endereço do app a testar (https://...):"
write_env URL_APP "$URL_APP"
step "Confirme que o deploy está atual: scripts/conferir-deploy.sh"
pause "Feito?"

stage "1/13 · Instalar nos dois aparelhos"
step "iPhone: Safari → abrir $URL_APP → Compartilhar → Adicionar à Tela de Início."
step "Android: Chrome → abrir $URL_APP → menu → Instalar app."
registrar R_01 "Instalar pelo Compartilhar (iPhone) e Chrome (Android)"

stage "2/13 · Offline e fila, sem duplicar"
step "Nos dois: modo avião, lance 2-3 lançamentos, religue a rede."
step "iPhone: abra o app e veja a fila subir. Android: veja subir."
step "Confira na lista dos dois aparelhos que nada duplicou."
registrar R_02 "Lançar offline, enviar a fila, sem duplicar"

stage "3/13 · Android: sync do service worker (ticket 33)"
step "Android: sem rede, lance 2 itens, FECHE o app (deslize para fora)."
step "Ligue a rede sem abrir o app e espere um pouco; depois abra e veja se subiram sozinhos."
registrar R_03 "Android: lançamentos sobem sozinhos com app fechado"

stage "4/13 · Conflito real entre os aparelhos"
step "Nos dois, offline: edite o MESMO lançamento (mesmo campo, valores diferentes)."
step "Religue um aparelho, depois o outro. Veja o conflito aparecer e decida-o."
registrar R_04 "Conflito entre os dois aparelhos e sua decisão"

stage "5/13 · DSQL: versão por campo e disputa (ticket 34)"
step "No DSQL (dev ou prod), após editar o mesmo lançamento nos dois aparelhos:"
step "  consulte lancamento_campos e veja uma versão por campo editado."
step "Edite ao mesmo tempo nos dois: deve terminar em conflito, não em erro 5xx."
registrar R_05 "DSQL: lancamento_campos grava versões; disputa vira conflito"

stage "6/13 · DSQL: recorrência, parcelamento, correção e exclusão (44, 46, 47)"
step "Dev: crie uma recorrência; confira os previstos gerados em lotes no DSQL."
step "Dia seguinte: logs da Lambda TarefaDiaria (00:07) com o automático realizado."
step "Repita com um parcelamento no cartão (parcelas em lotes; parcela realizada ao fechar a fatura anterior)."
step "Corrija e exclua um parcelamento longo (refazer/excluir em lotes; faturas criadas na 1ª correção). Veja o ticket 103."
registrar R_06 "Recorrência, TarefaDiaria, parcelamento, correção e exclusão no DSQL"

stage "7/13 · iPhone alguns dias sem abrir"
step "Deixe o iPhone alguns dias sem abrir o app, depois abra."
step "Confira que nada local se perdeu (senão, retomar o roteiro do ticket 17)."
registrar R_07 "iPhone parado: nada local perdido"

stage "8/13 · Jornada do ticket 42 nos dois celulares"
step "Android: atalho do ícone. iPhone: botão na Hoje."
step "Folha de detalhes, 'Repetir último', transferência."
step "Confirme: 'Transferência' no seletor de tipo; 'Repetir último' só com lançamentos de quem está no aparelho; data do resumo em dd/mm/aaaa."
registrar R_08 "Jornada do lançamento rápido (ticket 42)"

stage "9/13 · DSQL: parcelamento de 420 parcelas (ticket 98)"
step "Sem internet, lance um parcelamento de 420 parcelas no cartão, com várias categorias e tags; religue e envie."
step "Meça o POST /api/lancamentos/lote (CloudWatch da Lambda ou DevTools). Limite: 29 s."
note "Se não couber: baixar PARCELAS_POR_LOTE em web/src/dados/fila.ts ou gerar as parcelas depois de responder."
registrar R_09 "Lote de 420 parcelas (tempo medido)"

stage "10/13 · Sugestão pelo histórico (ticket 63)"
step "Nos dois celulares, sem internet: digite a descrição na folha de detalhes, escolha e corrija a sugestão."
step "No DSQL com histórico importado: meça tempo e tamanho de GET /api/sugestoes."
registrar R_10 "Sugestões: offline nos celulares e tempo/tamanho no DSQL"

stage "11/13 · DSQL: itens do planejamento (tickets 49 e 51)"
step "Confira se itens_do_planejamento aceita índice único em (mes, categoria_id)."
step "Crie um item num mês cheio e junte uma categoria com muito histórico: guardar_item_atual e a junção numa transação só; cabem nas 3.000 linhas? Senão, gravar em lotes."
registrar R_11 "Planejamento no DSQL: índice único e limite de 3.000 linhas"

stage "12/13 · DSQL: edição em lote grande (ticket 61)"
step "Aplique e desfaça uma edição em lote grande (POR_TRANSACAO = 50 por parte)."
step "Confira que cabe nas 3.000 linhas e o tempo de um lote de mil lançamentos (< 30 s da HTTP API)."
registrar R_12 "Edição em lote grande: aplicar, desfazer, tempo de 1000"

stage "13/13 · Verificações do projeto"
step "Rode as verificações do projeto e abra o PR para main (título '35: Teste manual nos dois celulares')."
registrar R_13 "Verificações rodando e PR aberto"

stage "Decisão: seguir ou plano B?"
say "Resumo da PWA nos dois aparelhos. Se decepcionou, discutir Capacitor (ADR 0005) antes de seguir."
ask DECISAO "Decisão (seguir / plano B) e por quê:"
write_env DECISAO "$DECISAO"
{
  echo; echo "## Answer"; echo
  printf '%s\n' "${RESULTADOS[@]}"
  echo "- Decisão: $DECISAO"
} > "${ENV_FILE%.env}-answer.md"
note "Texto para colar em '## Answer': ${ENV_FILE%.env}-answer.md"

finish
}

run_wizard "$@"; exit
